-- 095_meeting_reminder_email_feature.sql
--
-- Feature catalog row for the new Meeting Reminder Email tool (the
-- user's own request: "a tool in the app where the executive secretary
-- can send an email generated by the app through the associated gmail
-- account... directly from the app is fine... only sending to those
-- who have log-ins that include an email"). No new table -- recipients
-- are resolved live from meeting_type_members (who attends) joined to
-- people.profile_id -> profiles.email (who has a login with an email),
-- both of which already exist; this migration only grants access to
-- the tool itself.
--
-- Nobody gets it automatically; grant it to the Executive Secretary
-- calling (and Bishopric, if wanted) via /admin/calling-features, same
-- one-time bootstrapping step every new standalone-tool feature needs.
--
-- Idempotent: safe to re-run.

insert into features (key, label, category, sort_order) values
  ('meeting_reminder_email', 'Meeting Reminder Email', 'Tools', 14)
on conflict (key) do nothing;
